storyDrafts.forEach((story) => {
  const ending = story.content.pop();
  story.content.push(...storyExtensions[story.id], ...storyFurtherReading[story.id], ending);
});

const IMAGE_DIR = 'images/';
window.STORIES = storyDrafts.map((story) => ({
  ...story,
  cover: `${IMAGE_DIR}story-${String(story.id).padStart(2, '0')}.jpg`,
  illustration: `${IMAGE_DIR}story-${String(story.id).padStart(2, '0')}.jpg`
}));

const LIKE_KEY = 'pageturn-likes';
const THEME_KEY = 'pageturn-theme';
const FONT_KEY = 'pageturn-font-size';
const libraryState = { genre: 'All', search: '', sort: 'featured' };

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[character]);
}

function getLikedStories() {
  return JSON.parse(localStorage.getItem(LIKE_KEY) || '[]');
}

function saveLikedStories(ids) {
  localStorage.setItem(LIKE_KEY, JSON.stringify(ids));
}

function applyTheme(theme) {
  const dark = theme === 'dark';
  document.body.classList.toggle('dark', dark);
  document.querySelectorAll('.theme-toggle').forEach((button) => {
    button.textContent = dark ? '☀' : '☾';
    button.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode');
  });
}

function initializeTheme() {
  applyTheme(localStorage.getItem(THEME_KEY) || 'light');
  document.querySelectorAll('.theme-toggle').forEach((button) => {
    button.addEventListener('click', () => {
      const next = document.body.classList.contains('dark') ? 'light' : 'dark';
      localStorage.setItem(THEME_KEY, next);
      applyTheme(next);
    });
  });
}

function getFilteredStories() {
  const needle = libraryState.search.trim().toLowerCase();
  const filtered = window.STORIES.filter((story) => {
    const matchesGenre = libraryState.genre === 'All' || story.genre === libraryState.genre;
    const matchesSearch = `${story.title} ${story.author} ${story.genre}`.toLowerCase().includes(needle);
    return matchesGenre && matchesSearch;
  });
  if (libraryState.sort === 'title') filtered.sort((a, b) => a.title.localeCompare(b.title));
  else if (libraryState.sort === 'genre') filtered.sort((a, b) => a.genre.localeCompare(b.genre) || a.title.localeCompare(b.title));
  else filtered.sort((a, b) => a.id - b.id);
  return filtered;
}

function renderGenres() {
  const container = document.getElementById('genreFilters');
  if (!container) return;
  const genres = ['All', ...new Set(window.STORIES.map((story) => story.genre))];
  container.innerHTML = genres.map((genre) => `
    <button class="genre-chip ${libraryState.genre === genre ? 'active' : ''}" type="button" data-genre="${escapeHtml(genre)}" aria-pressed="${libraryState.genre === genre}">
      ${genre === 'All' ? 'All stories' : escapeHtml(genre)}
    </button>
  `).join('');
}

function renderGrid() {
  const grid = document.getElementById('bookGrid');
  if (!grid) return;
  const stories = getFilteredStories();
  const liked = getLikedStories();
  grid.innerHTML = stories.map((story) => `
    <article class="book-card">
      <div class="cover-wrap">
        <img class="book-cover" src="${escapeHtml(story.cover)}" alt="Cover art for ${escapeHtml(story.title)}" loading="lazy">
        <div class="cover-caption" aria-hidden="true">
          <span>${escapeHtml(story.genre)}</span>
          <strong>${escapeHtml(story.title)}</strong>
        </div>
        <div class="cover-overlay">
          <a class="read-button" href="read.html?id=${story.id}">Read story</a>
        </div>
        <button class="like-button ${liked.includes(story.id) ? 'liked' : ''}" type="button" data-like-id="${story.id}" aria-label="${liked.includes(story.id) ? 'Remove from saved stories' : 'Save story'}" aria-pressed="${liked.includes(story.id)}">${liked.includes(story.id) ? '♥' : '♡'}</button>
      </div>
      <div class="book-info">
        <span class="book-genre">${escapeHtml(story.genre)}</span>
        <a class="book-title" href="read.html?id=${story.id}">${escapeHtml(story.title)}</a>
        <p class="book-author">by ${escapeHtml(story.author)}</p>
        <div class="book-meta">
          <span>1 chapter</span>
          <button class="details-button" type="button" data-detail-id="${story.id}">View details</button>
        </div>
      </div>
    </article>
  `).join('');
  document.getElementById('resultCount').textContent = `${stories.length} ${stories.length === 1 ? 'story' : 'stories'}`;
  document.getElementById('emptyState').hidden = stories.length > 0;
}

function openDetails(storyId) {
  const story = window.STORIES.find((item) => item.id === storyId);
  const dialog = document.getElementById('detailsDialog');
  const content = document.getElementById('dialogContent');
  if (!story || !dialog || !content) return;
  content.innerHTML = `
    <div class="dialog-layout">
      <img src="${escapeHtml(story.cover)}" alt="Cover art for ${escapeHtml(story.title)}">
      <div>
        <p class="eyebrow">${escapeHtml(story.genre)}</p>
        <h3>${escapeHtml(story.title)}</h3>
        <p>By ${escapeHtml(story.author)}</p>
        <p>${escapeHtml(story.synopsis)}</p>
        <p><strong>${escapeHtml(story.chapterTitle)}</strong> · One complete chapter</p>
        <a class="button button-primary" href="read.html?id=${story.id}">Read story →</a>
      </div>
    </div>
  `;
  dialog.showModal();
}

function initializeLibrary() {
  if (!document.getElementById('bookGrid')) return;
  renderGenres();
  renderGrid();
  document.getElementById('searchInput').addEventListener('input', (event) => {
    libraryState.search = event.target.value;
    renderGrid();
  });
  document.getElementById('sortSelect').addEventListener('change', (event) => {
    libraryState.sort = event.target.value;
    renderGrid();
  });
  document.getElementById('genreFilters').addEventListener('click', (event) => {
    const button = event.target.closest('[data-genre]');
    if (!button) return;
    libraryState.genre = button.dataset.genre;
    renderGenres();
    renderGrid();
  });
  document.getElementById('bookGrid').addEventListener('click', (event) => {
    const likeButton = event.target.closest('[data-like-id]');
    if (likeButton) {
      const id = Number(likeButton.dataset.likeId);
      const liked = getLikedStories();
      saveLikedStories(liked.includes(id) ? liked.filter((item) => item !== id) : [...liked, id]);
      renderGrid();
      return;
    }
    const detailButton = event.target.closest('[data-detail-id]');
    if (detailButton) openDetails(Number(detailButton.dataset.detailId));
  });
  const dialog = document.getElementById('detailsDialog');
  document.querySelector('.dialog-close').addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', (event) => {
    if (event.target === dialog) dialog.close();
  });
}

function renderReaderError(message) {
  const error = document.getElementById('readerError');
  error.hidden = false;
  error.innerHTML = `${escapeHtml(message)} <a href="index.html#library">Return to the library</a>`;
  document.getElementById('readerView').hidden = true;
}

function updateProgress() {
  const track = document.querySelector('.progress-track');
  const bar = document.getElementById('progressBar');
  const label = document.getElementById('progressLabel');
  if (!track || !bar || !label) return;
  const scrollable = document.documentElement.scrollHeight - window.innerHeight;
  const progress = scrollable <= 0 ? 100 : Math.min(100, Math.max(0, window.scrollY / scrollable * 100));
  bar.style.width = `${progress}%`;
  track.setAttribute('aria-valuenow', String(Math.round(progress)));
  label.textContent = `${Math.round(progress)}% read`;
}

function initializeReader() {
  const reader = document.getElementById('readerView');
  if (!reader) return;
  const id = Number(new URLSearchParams(window.location.search).get('id'));
  const story = window.STORIES.find((item) => item.id === id);
  if (!story) {
    renderReaderError('That story could not be found.');
    return;
  }

  document.title = `${story.title} | Storyverse`;
  document.getElementById('storyCover').src = story.cover;
  document.getElementById('storyCover').alt = `Cover art for ${story.title}`;
  document.getElementById('storyIllustration').src = story.illustration;
  document.getElementById('storyIllustration').alt = `Story illustration for ${story.title}`;
  document.getElementById('illustrationCaption').textContent = `An illustration for ${story.title}`;
  document.getElementById('storyGenre').textContent = story.genre;
  document.getElementById('storyTitle').textContent = story.title;
  document.getElementById('storyAuthor').textContent = `by ${story.author}`;
  document.getElementById('storySynopsis').textContent = story.synopsis;
  document.getElementById('storyContent').innerHTML = `<h2>${escapeHtml(story.chapterTitle)}</h2>${story.content.map((paragraph) => `<p>${escapeHtml(paragraph).replace(/\n/g, '<br>')}</p>`).join('')}`;

  const likeButton = document.getElementById('likeButton');
  const updateLike = () => {
    const isLiked = getLikedStories().includes(story.id);
    likeButton.textContent = isLiked ? '♥ Saved' : '♡ Save';
    likeButton.classList.toggle('liked', isLiked);
    likeButton.setAttribute('aria-pressed', String(isLiked));
  };
  updateLike();
  likeButton.addEventListener('click', () => {
    const liked = getLikedStories();
    saveLikedStories(liked.includes(story.id) ? liked.filter((item) => item !== story.id) : [...liked, story.id]);
    updateLike();
  });

  const synopsis = document.getElementById('storySynopsis');
  const synopsisButton = document.getElementById('toggleSynopsis');
  synopsisButton.addEventListener('click', () => {
    synopsis.hidden = !synopsis.hidden;
    synopsisButton.textContent = synopsis.hidden ? 'Show synopsis' : 'Hide synopsis';
    synopsisButton.setAttribute('aria-expanded', String(!synopsis.hidden));
  });

  const content = document.getElementById('storyContent');
  const fontButton = document.getElementById('fontSizeButton');
  let fontSize = Math.min(26, Math.max(16, Number(localStorage.getItem(FONT_KEY)) || 18));
  content.style.fontSize = `${fontSize}px`;
  fontButton.addEventListener('click', () => {
    fontSize = fontSize >= 26 ? 16 : fontSize + 2;
    content.style.fontSize = `${fontSize}px`;
    localStorage.setItem(FONT_KEY, String(fontSize));
  });

  const index = window.STORIES.findIndex((item) => item.id === story.id);
  const previous = document.getElementById('prevStoryButton');
  const next = document.getElementById('nextStoryButton');
  if (index > 0) previous.href = `read.html?id=${window.STORIES[index - 1].id}`;
  else previous.hidden = true;
  if (index < window.STORIES.length - 1) next.href = `read.html?id=${window.STORIES[index + 1].id}`;
  else next.hidden = true;

  document.getElementById('readerError').hidden = true;
  reader.hidden = false;
  updateProgress();
  window.addEventListener('scroll', updateProgress, { passive: true });
}

document.addEventListener('DOMContentLoaded', () => {
  initializeTheme();
  initializeLibrary();
  initializeReader();
});
